CREATE POLICY "Members read own restored studio files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id IN ('plan-uploads','sketchup-uploads','tearsheet-uploads','user-outputs') AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Members upload own restored studio files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id IN ('plan-uploads','sketchup-uploads','tearsheet-uploads','user-outputs') AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Members replace own restored studio files" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id IN ('plan-uploads','sketchup-uploads','tearsheet-uploads','user-outputs') AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id IN ('plan-uploads','sketchup-uploads','tearsheet-uploads','user-outputs') AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Members delete own restored studio files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id IN ('plan-uploads','sketchup-uploads','tearsheet-uploads','user-outputs') AND (storage.foldername(name))[1] = auth.uid()::text);